#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
echo "==> step172: fix trial_ready WhatsApp text — write credentials into langs.en (not just body)"
DBJS=$(mktemp /tmp/db_step172.XXXXXX.js)
echo "" | base64 -d > "$DBJS"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" GSZ_ENV="$GSZ/.env" node "$DBJS" )
rm -f "$DBJS"
echo ""
echo "==> step172 OK  The trial WhatsApp message now renders from langs.en with the login credentials included. Claim a fresh trial to verify (old pending ones keep the old text)."
